import{_ as t,c as n,o as l,j as e,a as s}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易图通变卷三","description":"易图通变 - 易图通变卷三","frontmatter":{"title":"易图通变卷三","description":"易图通变 - 易图通变卷三"},"headers":[],"relativePath":"zh/classics/yitu-tongbian/004.md","filePath":"zh/classics/yitu-tongbian/004.md"}'),i={name:"zh/classics/yitu-tongbian/004.md"};function r(o,a,c,p,d,u){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"易图通变卷三",tabindex:"-1"},[s("易图通变卷三 "),e("a",{class:"header-anchor",href:"#易图通变卷三","aria-label":"Permalink to “易图通变卷三”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"宋雷思齐撰",-1),e("p",null,"道家以日月为易，始蹈常袭故，未始为然，卒究于大传，则未始不然。曰：「乾坤，其易之蕴邪？乾坤成列，而易立乎其中矣。乾坤毁，则无以见易，易不可见，则乾坤或几乎息矣。」是犹未识所见之易为何物也。则又曰：「乾坤，其易之门邪？乾，阳物也；坤，阴物也。阴阳合德而刚柔有体，以体天地之撰，以通神明之德。」是易之为物，有体可以见矣。则又曰：「辟户谓之乾，阖户谓之坤，一阖一辟谓之变，往来不穷谓之通。见乃谓之象，形乃谓之气，制而用之谓之法，利用出入，民咸用之谓之神。」是易之谓体者，又见其有用矣。故曰：「天地设位，而易行乎其中矣。」曰：「法象莫大乎天地，变通莫大乎四时，县象著明莫大乎日月。」曰：「广大配天地，变通配四时，阴阳之义配日月。」凡是数端，莫不举日月以征，则信其为易也完矣。夫易与天地准，能弥纶天地之道，仰观象于天，俯观法于地，则成象谓乾者，日也；效法谓坤者，月也。日象离，数极乎九，月象坎，数始乎一。凡九必对六，今云一者，一合天五为六，坎一乾六为水生成，所以为月者也。且天地乃乾坤之体，乾坤乃天地之用。惟天地定位，而上下气形有不易之分，故乾坤成列，而阴阳体用有变易之数。天地有常体而莫见其用，阴阳有常用而莫究其体。惟日月之体用兼著，故特著其义以配阴阳云尔。且明教以范围天地而不过，曲成万物而不遗者，特通乎昼夜之道而知也。夫昼夜之道，岂难知哉？百姓日用而不知尔。请略举其凡。乾，阳物者，日其类也。坤，阴物者，月其类也。阴阳成列而合德者，四时合序，日月合明。辟户谓乾，近则日之出旦，月之上弦，远则春之日夜分，而谓「启」也。阖户谓坤，近则日之入夕，月之下弦，远则秋之日，夜分而谓「闭」也。仰观其成象，则日之昼，月之望，夏之景长而至。俯察其效法，则夜之分，月之朔，冬之景短而至也。是以日往则月来，月往则日来，日月相推而明生焉。寒往则暑来，暑往则寒来，寒暑相推而岁成焉。变化者，进退之象也。刚柔者，昼夜之象也。日月运行，一寒一暑。故曰：天地之道，贞观者也。日月之道，贞明者也。天下之动，贞夫一者也。贞夫一也者，四时分至之中皆一也。而此特谓天下之动贞夫一，则正由坎之一也。一日之阳起，初动于夜分之际，固谓贞夫一也。一年之阳气，复动于冬朔之始，尤见其贞夫一者也。坎之数一，离之数九，坎离以一九为乾，离为日，坎为月，日月必合于月之初一为朔。而日不云朔，月乃云朔，南不云朔，北乃云朔。夫朔，逆度也。逆与日会，故谓之朔。以朔文观之，明著月之逆度者也。说卦曰：「易逆数也」。书亦曰：「平在朔易」，理实同也。由是以进乎日月之为易，其县象得不谓著明矣乎？故月之三五而盈少阴阳之七八，三五而阙老阴阳之九六，总之以地数三十而月尽，又河图法也。周天三百六十五度四分度之一，日每行一度，冬南夏北，为寒暑之中极。月行每十有三度而奇，与日之合者十有二朔，而岁常以备六阴六阳十有二月，天地节而四时成，是月之运行，劳亦甚矣。其称坎为劳卦者，不徒谓水也。此坎之一数不入于参两参伍之制，而特著其动之始也，中之始也。",-1),e("p",null,"合而言之，天地者体也，阴阳者用也。体者形所以用其气，用者气所以体其形。天以气体其形，故其形下包乎地。地以形用其气，故其气上行乎天。是天之气全体乎地之形，而地之形全用乎天之气。此又参两之制得以明之也。",-1),e("p",null,"一之始参，三之终参，皆天也，而并位乎平地之上。如乾者，老阳也，乃附于成数之六，阴位乎阴地，西北偏极乎退数之终。艮者，少阳也，乃附于成数之八，阴位乎阳地，东北偏，立乎进数之始。而特以坎中之一阳不在参两之用者，因其始生自然之一介，然特立于阴阳终始之际，起岁之朔，月之朔，以体生生之谓易，斯足以明地之体全用乎天矣。一始之两，二终之两，皆地也，而兼列于平地之上。如巽，少阴也，虽以附地生数之四，阴，位乃在东南偏，阳气升已过中之进数。坤，老阴也，虽以附地生数之二，阴，位犹在西南偏，阳气降未及中之退数。且兼两地并以奉中参天位之极，当天之极高，日之极中，斯足以明天之用全体乎地矣。以是知参两之制，非有日以定其昼夜长短，有月以更其朔望赢缩，则天地之气形体用，阴阳之变化生成，其升降进退之变通，分合出入之归宿，则恶从而讨其真是哉！",-1),e("p",null,"故尝由是以参之，制数之元矣。天一之始，自北而中，而分地二于西南，不得谓「天地定位」者，阳正而下，阴偏而上也。二得名坤，一不得名乾者，一起于坎也。由一参二以为三，以前而东，盖所以见人参于天地之中以生而动于震，因两其二而四附以顺而相入之巽，虚生其象以为四。然象非实体也，象天地与人极男女之相配以始者尔。一与三之阳，自然已各据其中，而二与四之未中，未有以正之，可遂已乎？故有待取用于成数之交合以成其正也。五虽虚位于中，而有其数可制其用。一交五而以其一相配而成六于乾，二交五而以其二相配而成七于兑，三交五而以其三相配而成八于艮，四交五而以其四相配而成九于离。然后始谓之成象。成象则谓之乾，而效法则谓之坤矣，乃得谓之「天地定位」也。其实一自合一，二自合二，三自合三，四自合四，特以交五而变尔。于是坎一之阳，合而成乾六之阴；坤二之阴，合而成兑七之阳；震三之阳，合而成艮八之阴；巽四之阴，合而成离九之阳。其始正者合而辅于偏，始偏者合而归之正。于是八卦成列，而象在其中矣。亦惟一之自中，坎独自若而不入于数，而河图参天两地，参伍错综之变，得以行乎其中也。故由参天之制皆用九，而知九为乾之用；由两地之制皆用六，而知六为坤之用。盖乾之始参于艮八而不足于数，则取震之一而九之。中参当阳极，而体数之全无余，不足则自九之终参，则取兑过中有余之三，以奉乾六之终而九之。两之始起数于震中之二，以合巽四之不足而六之。两之终起数于坤之本二，以合兑中有余之四而六之。是明参两九六所用之槩也。或有谓坤二与兑七而九，乾位自得六数，亦自成九六也。曾不识两之制皆终地上，参之制皆终地下，又焉得而易之哉？况乾本九也，今数乃损而六；坤本六也，今数乃增之而九者，尤足以明老阴之六变而之九，老阳之九变而之六，而卦爻之所以成九六也。由参天之用必九，两地之体必六。下系之首曰：「八卦成列，象在其中矣。因而重之，爻在其中矣。」而后世乃谓易画之重非由羲始，吾不信也。",-1),e("p",null,"且说卦谓「说言乎兑，成言乎艮」，凡再言。其「山泽通气」者，即咸卦也。咸之彖曰：二气感应以相与，止而说，天地感而万物化生，圣人感人心而天下和平。观其所感，而天地万物之情可见矣。其「雷风相薄」者，即恒卦也。恒之彖曰：「雷风相与，巽而动，天地之道，恒久而不已也。日月得天而能久照，四时变化而能久成，圣人久于其道，而天下化成。」观其所恒，而天地万物之情可见矣。溯求于下经之人道攸始，则说卦、重卦，其旨一毫不悖也。故愚谓重易断自羲始，不然，礼谓三易其经卦皆八，其别皆六十四，其欺我哉！求易之道，试以是进之。说卦曰：「圣人之作易也，参天两地而倚数，观变于阴阳而立卦，发挥于刚柔而生爻。」因参稽其所以参两者，其得于河图无间然矣。且「帝出乎震」一章，尤河图之大讲明也。特截自震起于泰中，环周而讫于艮，寓夏正之岁更尔。故曰：「终万物、始万物者，莫盛乎艮。」曰：「艮东北之卦，万物之所成终而所成始。」意盖谓又始于出乎震者也。此实孔子特以变通四时言也，而于通乎昼夜之道而知，则未及悉也。夫两之制，并起于平地以奉中参者，自春而秋，以分必极于夏之至者，亦昼之象也。始终之参，皆在地中者，自秋而春，以分必极于冬之至者，亦夜之象也。请以日用常行变而通之。则出乎震者，人之始作于旦也，古谓震旦，所以验也。齐乎巽者，动而相与之交也。相见乎离，则交际之极也。致役乎坤，则动极徐静也。说言乎兑，休且入也。自震至兑，此昼之体用，人所同见。至于战乎乾，卒取终参之制，其数之九，则存兑余之三，向晦入息于乾，六以终也。阴阳相薄，闭塞不用之时也。然终则有始，至于劳乎坎，则夜分之气复动，准于七日之复则同也。成言乎艮，则远接兑余之三，说言乎兑也。山泽通气，感而相与，虽止于其所，而时行则行，斯人事之又兴始者也。变化者，进退之象也；刚柔者，昼夜之象也。吾见自羲文以来，河图之一阴一阳，进退升降，往复循环，周流不息，开古讫今，远之一岁之冬夏，迩之一日之昼夜，莫不由斯道也。吾日用常行，不在它求，参天之道自艮始者于是乎在。其视太玄以七百二十九赞之准易，皇极以元会运世之旁通，各以一期之岁月日时为数例，视今通其变、极其数，于河图日可见之行也，岂不易简而理得哉！斯非至精变而神者欤！易图通变卷三。",-1)])])}const f=t(i,[["render",r]]);export{_ as __pageData,f as default};
